const esc = value => String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const steps = items => items.map((s,i)=>`<div class="step-item"><b>Step ${i+1}.</b> ${s}</div>`).join('');
const examplesHtml = examples => examples.map(e=>{const id=e.badge.toLowerCase().replace(/[^a-z0-9]+/g,'-');return `<article class="solved-example" id="example-${id}" data-example="${esc(e.badge)}"><div class="example-header"><span class="example-badge">${e.badge}</span><h3 class="example-title">${e.title}</h3></div><p class="example-question">${e.question}</p><button type="button" class="sol-toggle-btn example-btn" onclick="toggleExample(this)" aria-expanded="false" aria-controls="example-answer-${id}"><span>View Step-by-Step Solution</span><b aria-hidden="true">+</b></button><div class="example-solution-box" id="example-answer-${id}">${steps(e.steps)}<p class="thermal-callout"><strong>Result:</strong> ${e.answer}</p></div></article>`;}).join('');
